namespace QuantForge.Core;public sealed record ReleaseCandidateSummary(string AppVersion,string BuildCode,string Commit,string Tree,bool SourceValidated,bool AndroidNativeValidated,bool AndroidDeviceAccepted,bool WindowsNativeValidated,bool WindowsAccepted,bool StableEligible,bool LiveAuthorityEnabled,IReadOnlyList<string> Missing);public static class ReleaseCandidateSummaryRules{public static ReleaseCandidateSummary Create(string appVersion,string buildCode,string commit,string tree,ReleaseValidationMatrix android,ReleaseValidationMatrix windows){if(new[]{appVersion,buildCode,commit,tree}.Any(string.IsNullOrWhiteSpace))throw new InvalidOperationException("Release candidate identity is incomplete.");var missing=android.Missing.Select(x=>"android:"+x).Concat(windows.Missing.Select(x=>"windows:"+x)).Distinct(StringComparer.Ordinal).OrderBy(x=>x,StringComparer.Ordinal).ToArray();return new(appVersion,buildCode,commit,tree,android.SourceValidated&&windows.SourceValidated,android.NativeBuildValidated,android.DeviceAccepted,windows.NativeBuildValidated,windows.DeviceAccepted,android.StableEligible&&windows.StableEligible,false,missing);}}
